// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address initialOwner, address newOwner) public {
        vm.assume(newOwner != address(0));
        vm.assume(initialOwner != address(0));

        // Set initial owner
        vm.prank(initialOwner);
        c.transferOwnership(initialOwner);

        // Record owner before call
        address ownerBefore = c.owner();

        // Call owned() – reverts for non-owner in reference but not in buggy
        // In reference: only owner can call, so if msg.sender != owner, it reverts
        // We must handle both cases: if caller is owner, owner stays same; if not, revert
        // The property: after owned() (successful or not), owner does not change
        (bool success, ) = address(c).call(abi.encodeWithSignature("owned()"));

        address ownerAfter = c.owner();

        assertTrue(ownerBefore == ownerAfter);
    }
}

